<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ApiClient, errorMessage } from '../api'
import { dateTime } from '../domain'
import type { Job, NoticeSink, Product, Session } from '../types'
import type { Room, TaobaoEvent } from './types'
const props = defineProps<{ api: ApiClient; shopId: string; sessions: Session[]; products: Product[]; notify: NoticeSink; reload: () => Promise<void> }>()
const rooms = ref<Room[]>([]), events = ref<TaobaoEvent[]>([]), sessionId = ref(''), productId = ref(''), liveId = ref(''), comment = ref(''), messageId = ref(''), uniqueCode = ref('')
const error = ref(''), draftError = ref(''), bindingError = ref(''), replayError = ref(''), busy = ref(''), loading = ref(false)
const room = computed(() => rooms.value.find(r => r.session_id === sessionId.value))
const filtered = computed(() => events.value.filter(e => !sessionId.value || e.session_id === sessionId.value))
const eventLabels = { pending: '待处理', generating: '正在生成', drafted: '已存待审核稿', failed: '处理失败 / 结果待核对', ignored: '已忽略' }
watch(() => props.sessions, value => { if (!value.some(s => s.id === sessionId.value)) sessionId.value = value.find(s => s.status === 'active')?.id ?? value[0]?.id ?? '' }, { immediate: true })
watch(() => props.products, value => { if (!value.some(p => p.id === productId.value)) productId.value = value.find(p => p.active)?.id ?? '' }, { immediate: true })
watch(room, value => { liveId.value = value?.live_id ?? '' })
async function load() { if (loading.value) return; loading.value = true; error.value = ''; try { const [r, e] = await Promise.all([props.api.request<Room[]>('/taobao/rooms', { query: { shop_id: props.shopId } }), props.api.request<TaobaoEvent[]>('/taobao/events', { query: { shop_id: props.shopId } })]); rooms.value = r; events.value = e } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
onMounted(load)
async function bind() { if (busy.value || !sessionId.value) return; bindingError.value = ''; if (!/^[1-9]\d*$/.test(liveId.value.trim())) { bindingError.value = '直播间 ID 请输入正整数，不使用小数或科学计数法。'; return }; busy.value = 'bind'; try { await props.api.request('/taobao/rooms', { method: 'PUT', body: { shop_id: props.shopId, session_id: sessionId.value, live_id: liveId.value.trim() } }); await load(); props.notify('本地直播间映射已保存，不代表已取得平台权限。', 'info') } catch (cause) { bindingError.value = errorMessage(cause) } finally { busy.value = '' } }
async function replay() { if (busy.value || !room.value) return; replayError.value = ''; if (!comment.value.trim() || (!messageId.value.trim() && !uniqueCode.value.trim())) { replayError.value = '请填写评论与至少一种去重标识。'; return }; busy.value = 'replay'; try { const result = await props.api.request<{ event: TaobaoEvent; duplicate: boolean }>('/taobao/events/replay', { method: 'POST', body: { shop_id: props.shopId, session_id: sessionId.value, message_id: messageId.value.trim(), content: { liveId: room.value.live_id, uniqueCode: uniqueCode.value.trim(), comment: comment.value.trim() } } }); await load(); props.notify(result.duplicate ? '识别到重复回放，未重复入库。' : '回放已入库并标为本地测试来源；没有调用模型或播报。', 'info') } catch (cause) { replayError.value = errorMessage(cause) } finally { busy.value = '' } }
function newMessageId() { messageId.value = window.crypto.randomUUID() }
async function draft(event: TaobaoEvent) { if (busy.value || !productId.value || event.status !== 'pending') return; busy.value = event.id; draftError.value = ''; try { const job = await props.api.request<Job>('/taobao/events/' + event.id + '/draft', { method: 'POST', body: { shop_id: props.shopId, product_id: productId.value }, timeout: 125_000 }); props.notify(job.status === 'blocked' ? '话术需要人工处理，请到直播工作台查看。' : '待审核稿已保存，请到直播工作台人工审核。', 'info'); await props.reload() } catch (cause) { draftError.value = errorMessage(cause) } finally { busy.value = ''; await load() } }
async function poll() { if (busy.value) return; busy.value = 'poll'; error.value = ''; try { const value = await props.api.request<{ received: number; stored: number; duplicates: number; ignored: number; confirmed: number }>('/taobao/poll', { method: 'POST', body: { shop_id: props.shopId }, timeout: 50_000 }); await load(); props.notify('本次接收 ' + value.received + '，入库 ' + value.stored + '，去重 ' + value.duplicates + '，忽略 ' + value.ignored + '，平台确认 ' + value.confirmed + '。', 'info') } catch (cause) { error.value = errorMessage(cause) } finally { busy.value = '' } }
</script>
<template>
  <div class="settings-grid"><section class="panel padded"><form class="form-stack" @submit.prevent="bind"><h2>绑定本地场次</h2><label>场次<select v-model="sessionId" required><option value="">先创建场次</option><option v-for="session in sessions" :key="session.id" :value="session.id">{{ session.title }}</option></select></label><label>淘宝直播间 live_id<input v-model="liveId" required inputmode="numeric" maxlength="32" placeholder="输入实际直播间 ID；本地回放可使用测试房间标识" /></label><p class="hint">只保存本地映射。回放与正式消息使用不同来源，不会自动登录、开始直播或确认平台消息。</p><div v-if="bindingError" class="alert error" role="alert">{{ bindingError }}</div><button class="button secondary" :disabled="!!busy || !sessionId">{{ busy === 'bind' ? '保存中…' : '保存场次绑定' }}</button></form></section>
  <section class="panel padded"><form class="form-stack" @submit.prevent="replay"><h2>本地评论回放</h2><p class="hint">无需淘宝密钥。先绑定场次，再用真实结构测试入库和去重；不会自动调用 DeepSeek。</p><label>回放评论<textarea v-model="comment" required rows="3" maxlength="2000" /></label><div class="form-row"><label>message_id<input v-model="messageId" maxlength="200" placeholder="至少填写一种标识" /></label><label>uniqueCode<input v-model="uniqueCode" maxlength="200" placeholder="优先作为去重标识" /></label></div><button class="inline-button" type="button" @click="newMessageId">生成新的本地消息标识</button><div v-if="replayError" class="alert error" role="alert">{{ replayError }}</div><button class="button primary" :disabled="!!busy || !room">{{ busy === 'replay' ? '入库中…' : '回放入库' }}</button><p v-if="!room" class="hint">当前场次尚未绑定直播间。</p></form></section></div>
  <section class="panel events-panel"><div class="panel-title"><h2>评论事件 · 最近 100 条</h2><div class="row-actions"><button class="button secondary small" :disabled="!!busy" @click="poll">手动拉取平台消息</button><button class="button ghost small" :disabled="loading" @click="load">刷新</button></div></div><div class="panel-toolbar"><label>生成回复使用的商品<select v-model="productId"><option value="">请选择商品</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.title }}</option></select></label><p class="hint">生成会调用已配置的 DeepSeek，仅创建待审核稿；失败或结果不明不会自动重试。</p></div><div v-if="error || draftError" class="alert error inset-alert" role="alert">{{ error || draftError }}</div><div v-if="!filtered.length" class="empty-state compact"><h3>当前场次暂无评论事件</h3><p>使用本地回放验证去重，或配置获准的淘宝应用后手动拉取。</p></div><div v-else class="knowledge-list"><article v-for="event in filtered" :key="event.id" class="knowledge-item"><div class="knowledge-copy"><div class="record-badges"><span class="badge" :class="event.source === 'replay' ? 'warning' : 'neutral'">{{ event.source === 'replay' ? '本地回放' : '淘宝来源' }}</span><span class="badge neutral">{{ eventLabels[event.status] }}</span><small class="muted">{{ dateTime(event.received_at) }}</small></div><p class="event-comment">{{ event.comment }}</p><p v-if="event.job_id" class="secondary-line mono">任务 {{ event.job_id }}</p><p v-if="event.error_code" class="danger-text small-text">{{ event.error_code }}</p></div><button class="button secondary small" :disabled="!!busy || !productId || event.status !== 'pending'" @click="draft(event)">{{ busy === event.id ? '生成中…' : '生成待审核稿' }}</button></article></div></section>
</template>
